def stored_answers(model: str) -> list[int | None]:
    """The model's parsed replies: an int for each valid one, None for each invalid one."""
    replies = STORED.get(model, {"replies": {}})["replies"]
    return [answer for reply, count in replies.items() for answer in [parse_reply(reply)] * count]


@kbench.task(name="RandomBench Last Digit", description="The effective number of last digits among the model's random integers from 0 to 99, out of 10. 1 for a perfect random generator.")
def score(llm) -> tuple[float, float]:
    answers = stored_answers(llm.name)
    if not answers:
        # A model RandomBench doesn't cover, such as .env's in a local run
        # (D12), or one whose every call failed, such as Grok 4.5 (4.10).
        print(f"{llm.name} has no stored replies: no score")
        return False
    stored = STORED[llm.name]
    valid = sum(a is not None for a in answers)
    print(f"{llm.name}: {len(answers)} replies from runs {', '.join(stored['runs'])},"
          f" {valid} of them valid, and {stored['failed']} failed calls")
    value, half_width = score_answers(answers)[SCORE], score_intervals(answers)[SCORE]
    if value is None:
        print(f"{SCORE}: no score below {MIN_VALID} valid answers")
        return False
    print(f"{SCORE}: {value:.4f} ± {half_width:.4f}")
    return value, half_width


# %%
# On Kaggle, kbench.llm is the -m model, or the server's default in a push's
# creation run. Locally it's LLM_DEFAULT from .env. Assigned, so the notebook
# doesn't display the run: the display would crash on False after the run
# file is written (1.3). The local console UI crashes the same way, so a
# local run on .env's model, which has no stored replies, ends in a TypeError
# once its run file is written.
run = score.run(kbench.llm)

